#include "ej-20-48-tipos-y-formatos.h"
bool metadata_imagen_valida(const metadata_imagen_t *m){if(!m||m->formato<FORMATO_JPEG||m->formato>FORMATO_SVG||m->modo<COLOR_ESCALA_GRISES||m->modo>COLOR_INDEXADO||m->ancho<=0||m->alto<=0)return false;if(m->formato==FORMATO_SVG?m->profundidad_bits!=0:m->profundidad_bits<=0)return false;if(m->tiene_transparencia&&!(m->formato==FORMATO_PNG||m->formato==FORMATO_GIF||m->formato==FORMATO_WEBP||m->formato==FORMATO_TIFF||m->formato==FORMATO_SVG))return false;if(m->es_animado&&m->formato!=FORMATO_GIF&&m->formato!=FORMATO_WEBP)return false;return true;}
